-- Select all columns
SELECT * FROM Customers;

-- Select specific columns
SELECT FirstName, LastName, Email FROM Customers;

-- Distinct values
SELECT DISTINCT Country FROM Customers;

-- Top N rows
SELECT TOP 10 * FROM Orders;
SELECT TOP 10 PERCENT * FROM Orders;

-- Aliases
SELECT FirstName AS 'First Name', LastName + ', ' + FirstName AS 'Full Name'
FROM Customers;

SELECT COUNT(*) AS TotalCustomers FROM Customers;

SELECT * FROM Products WHERE Price > 100;
SELECT * FROM Products WHERE Category = 'Electronics';
SELECT * FROM Products WHERE Price BETWEEN 50 AND 200;
SELECT * FROM Products WHERE Category IN ('Electronics', 'Books');
SELECT * FROM Customers WHERE Name LIKE 'J%';
SELECT * FROM Orders WHERE ShippedDate IS NULL;
SELECT * FROM Products WHERE Price > 100 AND Stock > 0;
SELECT * FROM Products WHERE NOT Category = 'Electronics';

-- Ascending (default)
SELECT * FROM Products ORDER BY Price ASC;

-- Descending
SELECT * FROM Products ORDER BY Price DESC;

-- Multiple columns
SELECT * FROM Products ORDER BY Category ASC, Price DESC;

-- With alias
SELECT Name, Price * 1.1 AS NewPrice FROM Products ORDER BY NewPrice DESC;

-- Offset/Fetch (pagination)
SELECT * FROM Products ORDER BY Id
OFFSET 10 ROWS FETCH NEXT 5 ROWS ONLY;

-- Scalar subquery
SELECT Name, (SELECT MAX(Price) FROM Products) AS MaxPrice
FROM Products;

-- IN subquery
SELECT Name FROM Customers
WHERE Id IN (SELECT CustomerId FROM Orders WHERE Amount > 500);

-- EXISTS subquery
SELECT Name FROM Customers C
WHERE EXISTS (SELECT 1 FROM Orders O WHERE O.CustomerId = C.Id);

-- Correlated subquery
SELECT Name, (SELECT COUNT(*) FROM Orders O WHERE O.CustomerId = C.Id)
FROM Customers C;

-- PIVOT
SELECT Year, [Jan], [Feb], [Mar]
FROM (
  SELECT Year, Month, Amount FROM Sales
) AS Source
PIVOT (
  SUM(Amount) FOR Month IN ([Jan], [Feb], [Mar])
) AS PivotTable;

-- Clustered index (table data sorted)
CREATE CLUSTERED INDEX IX_Orders_Date ON Orders(OrderDate);

-- Non-clustered index
CREATE NONCLUSTERED INDEX IX_Orders_Customer ON Orders(CustomerId);

-- Unique index
CREATE UNIQUE INDEX IX_Users_Email ON Users(Email);

-- Composite index
CREATE INDEX IX_Orders_CustDate ON Orders(CustomerId, OrderDate);

-- Included columns (covering index)
CREATE INDEX IX_Orders_Covering ON Orders(CustomerId)
INCLUDE (Amount, OrderDate);

BEGIN TRANSACTION;

BEGIN TRY
  INSERT INTO Accounts (Name, Balance) VALUES ('Alice', 1000);
  INSERT INTO Accounts (Name, Balance) VALUES ('Bob', 500);

  UPDATE Accounts SET Balance = Balance - 100 WHERE Name = 'Alice';
  UPDATE Accounts SET Balance = Balance + 100 WHERE Name = 'Bob';

  COMMIT TRANSACTION;
END TRY
BEGIN CATCH
  IF @@TRANCOUNT > 0
    ROLLBACK TRANSACTION;

  SELECT
    ERROR_NUMBER() AS ErrorNumber,
    ERROR_MESSAGE() AS ErrorMessage;
END CATCH;

CREATE PROCEDURE GetCustomerOrders
  @CustomerId INT,
  @MinAmount DECIMAL(10,2) = 0
AS
BEGIN
  SET NOCOUNT ON;

  SELECT O.*, C.Name AS CustomerName
  FROM Orders O
  INNER JOIN Customers C ON O.CustomerId = C.Id
  WHERE O.CustomerId = @CustomerId
    AND O.Amount >= @MinAmount;

  RETURN @@ROWCOUNT;
END;

-- Execute
EXEC GetCustomerOrders @CustomerId = 1, @MinAmount = 100;

-- Scalar function
CREATE FUNCTION dbo.GetDiscount(@Price DECIMAL(10,2))
RETURNS DECIMAL(10,2)
AS
BEGIN
  RETURN CASE WHEN @Price > 100 THEN @Price * 0.9 ELSE @Price END;
END;

-- Table-valued function
CREATE FUNCTION dbo.GetActiveCustomers()
RETURNS TABLE
AS
RETURN (
  SELECT * FROM Customers WHERE IsActive = 1
);

-- Usage
SELECT dbo.GetDiscount(150) AS DiscountedPrice;
SELECT * FROM dbo.GetActiveCustomers();

CREATE TRIGGER trg_AuditOrders
ON Orders
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
  SET NOCOUNT ON;

  IF EXISTS (SELECT * FROM inserted)
    INSERT INTO OrderAudit (OrderId, Action, ChangedAt)
    SELECT Id, 'UPDATE', GETDATE() FROM inserted;

  IF EXISTS (SELECT * FROM deleted)
    INSERT INTO OrderAudit (OrderId, Action, ChangedAt)
    SELECT Id, 'DELETE', GETDATE() FROM deleted;
END;

-- Local temp table (#)
CREATE TABLE #TempOrders (
  OrderId INT,
  Total DECIMAL(10,2)
);

INSERT INTO #TempOrders
SELECT Id, Amount FROM Orders WHERE Amount > 100;

SELECT * FROM #TempOrders;
DROP TABLE #TempOrders;

-- Table variable
DECLARE @Results TABLE (
  Id INT,
  Name VARCHAR(100)
);

INSERT INTO @Results SELECT Id, Name FROM Customers;

CREATE VIEW vw_CustomerOrders AS
SELECT C.Name, O.Id AS OrderId, O.Amount, O.OrderDate
FROM Customers C
INNER JOIN Orders O ON C.Id = O.CustomerId;

-- Use the view
SELECT * FROM vw_CustomerOrders WHERE Amount > 100;

-- Indexed view (materialized)
CREATE VIEW vw_OrderSummary WITH SCHEMABINDING AS
SELECT CustomerId, COUNT_BIG(*) AS OrderCount, SUM(Amount) AS Total
FROM dbo.Orders
GROUP BY CustomerId;

CREATE UNIQUE CLUSTERED INDEX IX_vw_OrderSummary ON vw_OrderSummary(CustomerId);

-- IDENTITY column (auto-increment)
CREATE TABLE Products (
  Id INT IDENTITY(1,1) PRIMARY KEY,
  Name NVARCHAR(100)
);

-- SET IDENTITY_INSERT for explicit insert
SET IDENTITY_INSERT Products ON;
INSERT INTO Products (Id, Name) VALUES (100, 'Special');
SET IDENTITY_INSERT Products OFF;

-- Sequence
CREATE SEQUENCE OrderSeq START WITH 1000 INCREMENT BY 1;
INSERT INTO Orders (Id, Amount) VALUES (NEXT VALUE FOR OrderSeq, 250);
SELECT NEXT VALUE FOR OrderSeq AS NextId;

-- Store JSON as NVARCHAR
DECLARE @json NVARCHAR(MAX) = '{"Name":"John","Age":30}';

-- Parse JSON
SELECT JSON_VALUE(@json, '$.Name') AS Name, JSON_VALUE(@json, '$.Age') AS Age;

-- JSON from table column
SELECT Id, JSON_VALUE(Data, '$.Name') AS Name
FROM Users;

-- FOR JSON (export as JSON)
SELECT Name, Email FROM Customers
FOR JSON AUTO;

-- OPENJSON (parse JSON array)
SELECT * FROM OPENJSON('[{"Id":1,"Name":"A"},{"Id":2,"Name":"B"}]')
  WITH (Id INT, Name NVARCHAR(50));

-- CROSS APPLY (inner join with TVF)
SELECT C.Name, T.Total
FROM Customers C
CROSS APPLY (
  SELECT SUM(Amount) AS Total FROM Orders WHERE CustomerId = C.Id
) T;

-- OUTER APPLY (left join with TVF)
SELECT C.Name, T.Total
FROM Customers C
OUTER APPLY (
  SELECT SUM(Amount) AS Total FROM Orders WHERE CustomerId = C.Id
) T;

-- IF...ELSE
DECLARE @Count INT = (SELECT COUNT(*) FROM Orders);
IF @Count > 100
  PRINT 'High volume'
ELSE IF @Count > 50
  PRINT 'Medium volume'
ELSE
  PRINT 'Low volume';

-- WHILE loop
DECLARE @i INT = 1;
WHILE @i <= 5
BEGIN
  PRINT CONCAT('Iteration ', @i);
  SET @i = @i + 1;
END;
